// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 time) public {
        time = bound(time, 1, type(uint256).max - 1);
        vm.warp(time);
        vm.deal(address(this), 10 ether);
        (bool success, ) = address(c).call{value: 10 ether}("");
        assertTrue(success && c.pastBlockTime() == block.timestamp);
    }
}

